-- Thêm Folio, Pixform, Signature vào site_content (en, vi), trước "This portfolio".
-- Chạy một lần trong Supabase SQL Editor; chạy lại không bị trùng. Sau đó vào /admin bấm "Lưu & xuất bản" để xoá cache.

update public.site_content set data = jsonb_insert(jsonb_insert(jsonb_insert(data, '{projects,items,-1}', '{"name":"Folio","kind":"PDF page organizer","year":"2026","description":"Reorder, rotate and delete PDF pages right in the browser, built for a supermarket cashier. Files never leave the device, pages are copied byte for byte and checked before download.","stack":["React","TypeScript","pdf-lib","pdf.js","Tailwind CSS"],"url":"https://hongquan-folio.vercel.app","study":{"role":"Design and development","context":"A supermarket cashier needs to merge and reorder pages from several invoice PDFs without altering their content, and without uploading them to a server.","did":["Open several PDFs, drag whole groups of pages to reorder, rotate, delete, undo and redo with shortcuts","Copy pages intact with pdf-lib: content streams, fonts and images keep their bytes, nothing is re-rendered as images","Verify every exported page against the original (content, text, size, rotation) and block the download on any difference","Download files embedded in the PDF as-is, such as e-invoice XML","Mobile layout with bottom sheets and back-button handling; two UI themes that switch without losing the open document"],"outcome":"In real use for sorting invoices; everything runs in the browser, with no server or database."}}'::jsonb), '{projects,items,-1}', '{"name":"Pixform","kind":"Image converter","year":"2026","description":"Batch-convert images between PNG, JPEG, WebP, AVIF, GIF, BMP, ICO and TIFF in the browser, detecting each file''s real format and downloading them as a ZIP.","stack":["React","TypeScript","WebAssembly","Vite"],"url":"https://hongquan-pixform.vercel.app","study":{"role":"Design and development","context":"Converting an image usually means uploading it to some unknown website. Pixform does it on the user''s own device, iPhone HEIC photos included.","did":["Detect the real format from magic bytes and flag files whose extension lies about their content","Read PNG, JPEG, WebP, AVIF, GIF, BMP, ICO, TIFF, HEIC and SVG; write 8 formats with quality and background controls","Use the browser''s encoders and fall back to WebAssembly encoders where WebP or AVIF isn''t supported","Load heavy codecs (HEIC, AVIF, TIFF) only when needed; show size before and after, download one by one or as a ZIP"],"outcome":"Runs entirely in the browser; images are never uploaded."}}'::jsonb), '{projects,items,-1}', '{"name":"Signature","kind":"PDF signing in the browser","year":"2026","description":"Draw a handwritten signature with a finger, mouse or pen and place it anywhere in a PDF. Original content stays byte for byte, and the file never leaves the device.","stack":["React","TypeScript","pdf-lib","pdf.js","Vitest"],"url":"https://hongquan-signature.vercel.app","study":{"role":"Design and development","context":"Sign a PDF quickly on a phone or laptop without installing an app or uploading the document to a third-party service.","did":["Draw a signature on screen and place the signature, the full name or both; drag to move, rotate and resize","Match page frames and rotation between pdf.js (display) and pdf-lib (writing), ignoring stray taps and extra fingers","Render Vietnamese names as images, since pdf-lib''s standard fonts can''t encode the diacritics","Re-read the signed file and check page count, sizes, original content and signature count before allowing the download","On phones, share the signed file straight through the system share sheet"],"outcome":"An image signature, not a certificate-based digital signature; geometry and signing are covered by Vitest tests."}}'::jsonb)
where key = 'en' and not (data->'projects'->'items' @> '[{"url":"https://hongquan-folio.vercel.app"}]');

update public.site_content set data = jsonb_insert(jsonb_insert(jsonb_insert(data, '{projects,items,-1}', '{"name":"Folio","kind":"Công cụ sắp xếp trang PDF","year":"2026","description":"Sắp xếp, xoay, xoá trang PDF ngay trên trình duyệt cho thủ quỹ siêu thị. File không rời máy, trang được chép nguyên byte và tự kiểm tra trước khi cho tải.","stack":["React","TypeScript","pdf-lib","pdf.js","Tailwind CSS"],"url":"https://hongquan-folio.vercel.app","study":{"role":"Thiết kế và phát triển","context":"Thủ quỹ siêu thị cần gộp và sắp xếp lại trang từ nhiều file PDF hoá đơn mà không được làm sai lệch nội dung, và không muốn tải file lên máy chủ.","did":["Mở nhiều PDF, kéo thả cả nhóm trang để đổi thứ tự, xoay, xoá, hoàn tác/làm lại bằng phím tắt","Chép trang nguyên vẹn bằng pdf-lib: content stream, font, ảnh giữ nguyên byte, không render lại thành ảnh","Kiểm tra toàn vẹn từng trang của file xuất so với file gốc (nội dung, chữ, kích thước, góc xoay); sai lệch là chặn tải","Tải nguyên bản file đính kèm trong PDF, ví dụ XML hoá đơn điện tử","Giao diện mobile có bottom sheet, nút back đóng sheet; hai bộ giao diện chuyển qua lại không mất tài liệu"],"outcome":"Đang dùng thật cho việc sắp xếp hoá đơn; mọi xử lý chạy trên trình duyệt, không có máy chủ hay database."}}'::jsonb), '{projects,items,-1}', '{"name":"Pixform","kind":"Công cụ chuyển định dạng ảnh","year":"2026","description":"Chuyển hàng loạt ảnh giữa PNG, JPG, WebP, AVIF, GIF, BMP, ICO, TIFF ngay trên trình duyệt, tự nhận định dạng thật của file và tải về dạng ZIP.","stack":["React","TypeScript","WebAssembly","Vite"],"url":"https://hongquan-pixform.vercel.app","study":{"role":"Thiết kế và phát triển","context":"Đổi định dạng ảnh thường phải tải ảnh lên một website lạ. Pixform làm việc đó ngay trên máy người dùng, kể cả ảnh HEIC từ iPhone.","did":["Nhận diện định dạng thật bằng magic bytes, báo rõ khi đuôi file không khớp nội dung","Đọc PNG, JPG, WebP, AVIF, GIF, BMP, ICO, TIFF, HEIC, SVG; ghi ra 8 định dạng, chỉnh chất lượng và màu nền","Dùng encoder của trình duyệt, tự chuyển sang encoder WebAssembly khi trình duyệt không hỗ trợ WebP/AVIF","Thư viện nặng (HEIC, AVIF, TIFF) chỉ tải khi cần; xem dung lượng trước/sau, tải từng file hoặc gộp ZIP"],"outcome":"Chạy hoàn toàn trên trình duyệt, ảnh không bị tải lên máy chủ."}}'::jsonb), '{projects,items,-1}', '{"name":"Ký PDF","kind":"Ký PDF trên trình duyệt","year":"2026","description":"Vẽ chữ ký tay bằng ngón tay, chuột hoặc bút rồi đặt lên một hay nhiều chỗ trong PDF. Nội dung gốc giữ nguyên từng byte, file không rời máy.","stack":["React","TypeScript","pdf-lib","pdf.js","Vitest"],"url":"https://hongquan-signature.vercel.app","study":{"role":"Thiết kế và phát triển","context":"Ký nhanh một file PDF trên điện thoại hay máy tính mà không cần cài app hay tải tài liệu lên dịch vụ bên ngoài.","did":["Vẽ chữ ký trên màn hình, đặt chữ ký, họ tên hoặc cả hai lên trang; kéo để di chuyển, xoay, đổi cỡ","Khớp khung trang và góc xoay giữa pdf.js (hiển thị) và pdf-lib (ghi), bỏ qua chạm nhầm và ngón tay thừa","Vẽ họ tên tiếng Việt thành ảnh vì font chuẩn của pdf-lib không mã hoá được dấu","Đọc lại file đã ký để kiểm tra số trang, kích thước, nội dung gốc và số chữ ký trước khi cho tải","Trên điện thoại, chia sẻ file đã ký thẳng qua bảng chia sẻ của hệ điều hành"],"outcome":"Đây là chữ ký hình ảnh, không phải chữ ký số; phần hình học và ký có test bằng Vitest."}}'::jsonb)
where key = 'vi' and not (data->'projects'->'items' @> '[{"url":"https://hongquan-folio.vercel.app"}]');

